mapper.select:
SELECT digital_image_id, name,url
FROM t_digital_image

    user_id = #{userId} AND type = 0
    
        AND digital_image_id < #{lastCursorId}
    

ORDER BY digital_image_id DESC
LIMIT #{size}

SELECT digital_image_id, name,url
FROM t_digital_image

    user_id = #{userId} AND type = 1
    
        AND digital_image_id < #{lastCursorId}
    

ORDER BY digital_image_id DESC
LIMIT #{size}

SELECT digital_image_id, name,url
FROM t_digital_image

    user_id IS NULL AND type = 0
    
        AND digital_image_id < #{lastCursorId}
    

ORDER BY digital_image_id DESC
LIMIT #{size}

SELECT digital_image_id, name,url
FROM t_digital_image

    user_id IS NULL AND type = 1
    
        AND digital_image_id < #{lastCursorId}
    

ORDER BY digital_image_id DESC
LIMIT #{size}
